#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
static inline uint64_t cntv(void){ uint64_t v; asm volatile("mrs %0, cntvct_el0":"=r"(v)); return v; }
#define NITER 1000000
static uint64_t bench(void (*fn)(void*), void* arg, const char* name, double per){
  uint64_t t0=cntv(); for(int i=0;i<NITER;i++) fn(arg); uint64_t t1=cntv();
  double cyc=(double)(t1-t0)/NITER/per;  // cntvct at 100MHz? measure per first
  printf("%-34s %10.2f cycles/op (cntv ticks/op=%.2f)\n", name, cyc, (double)(t1-t0)/NITER);
  return t1-t0;
}
// 1. integer add chain
static void iadd(void*a){ asm volatile("mov x9,#0; add x9,x9,1; add x9,x9,1; add x9,x9,1; add x9,x9,1; add x9,x9,1; add x9,x9,1; add x9,x9,1; add x9,x9,1":::"x9"); }
int main(){
  // calibrate cntvct frequency: assume 2.6GHz CPU; measure via known 4-cycle fadd chain
  printf("cntvct ticks per NITER for 8 dependent adds: ");
  void*dummy=NULL;
  bench(iadd, dummy, "8x dependent int adds", 1.0);
  return 0;
}
EOF
