#include <stdio.h>
#include <stdint.h>
static inline uint64_t cntv(void){ uint64_t v; asm volatile("mrs %0, cntvct_el0":"=r"(v)); return v; }
#define REP 10000
#define UNROLL 100
// Each iteration: UNROLL dependent adds => UNROLL cycles @1cyc
static void iadd(void){ 
  uint64_t t=0;
  for(int r=0;r<REP;r++){
    asm volatile(
      "mov x9,%0\n"
      "1000: .rept 100\n add x9,x9,1\n .endr\n mov %0,x9\n"
      : "+r"(t) :: "x9");
  }
}
int main(){
  uint64_t t0=cntv(); iadd(); uint64_t t1=cntv();
  double ticks_per_100add = (double)(t1-t0)/REP;
  printf("ticks(100MHz) per 100 dependent adds = %.3f\n", ticks_per_100add);
  printf("→ CPU cycles per dependent add (assuming 2.6GHz) = %.3f\n", ticks_per_100add*26.0/100.0);
  return 0;
}
EOF
