  uint64_t t0=cntv(); fn(arg); uint64_t t1=cntv();
  double cyc = (double)(t1-t0)/REP * 26.0 / U;  // cycles per op
  printf("%-40s %8.2f cyc/op\n", name, cyc); return cyc;
}
// dependent int add
static void b_iadd(uint64_t n){ uint64_t t=0; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n .rept 100\n add x9,x9,1\n .endr\n mov %0,x9":"+r"(t)::"x9"); } (void)n; }
// independent int adds (throughput)
static void b_iadd_t(uint64_t n){ uint64_t t=0; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n .rept 25\n add x9,x9,#1\n add x10,x9,x9\n add x11,x10,x9\n add x12,x11,x9\n .endr\n mov %0,x9":"+r"(t)::"x9","x10","x11","x12"); } (void)n; }
// dependent FADD (single s register)
static void b_fadd(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n fadd s0,s0,s1\n .endr":::); } (void)n; }
// dependent FMUL
static void b_fmul(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n fmul s0,s0,s1\n .endr":::); } (void)n; }
// dependent FSQRT (common proxy for divider)
static void b_fsqrt(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n fsqrt s0,s0\n .endr":::); } (void)n; }
// dependent FDIV
static void b_fdiv(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 50\n fdiv s0,s0,s1\n fdiv s0,s0,s1\n .endr":::); } (void)n; }
// integer MUL dependent
static void b_imul(uint64_t n){ uint64_t t=1; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n .rept 100\n mul x9,x9,x9\n .endr\n mov %0,x9":"+r"(t)::"x9"); } (void)n; }
// integer DIV dependent
static void b_idiv(uint64_t n){ uint64_t t=3; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n mov x10,#7\n .rept 100\n udiv x9,x10,x9\n .endr\n mov %0,x9":"+r"(t)::"x9","x10"); } (void)n; }
// CRC32
static void b_crc(uint64_t n){ uint64_t t=0; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n mov x10,#0x12345678\n .rept 100\n crc32x x9,x9,x10\n .endr\n mov %0,x9":"+r"(t)::"x9","x10"); } (void)n; }
// AESD (single round) dependent
static void b_aes(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n aesd v0.16b, v1.16b\n .endr":::); } (void)n; }
// SHA256H dependent
static void b_sha(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n sha256h q0,q1,v2.4s\n .endr":::); } (void)n; }
// LSE atomic: CAS dependent
static void b_cas(uint64_t n){ uint64_t t=0; for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,%0\n .rept 100\n casal x9,x9,[x28]\n .endr\n mov %0,x9":"+r"(t)::"x9","memory"); } (void)n; }
// load-to-use L1: dependent loads from same cache line
static uint64_t buf[1024];
static void b_ld(uint64_t n){ uint64_t** p=(uint64_t**)&buf[0]; for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n ldr x28,[x28]\n .endr":::"x28"); } (void)n; }
// store throughput
static void b_st(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,sp\n .rept 100\n str x10,[x9,#0]\n .endr":::); } (void)n; }
// DC ZVA
static void b_zva(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile("mov x9,sp\n .rept 100\n dc zva, x9\n .endr":::"x9"); } (void)n; }
// branch: B.cond not-taken throughput
static void b_br(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile("cmp x0,x0\n .rept 100\n b.eq 2000f\n2000: .endr":::); } (void)n; }
// NOPs (max retire width check)
static void b_nop(uint64_t n){ for(uint64_t r=0;r<REP;r++){ asm volatile(".rept 100\n nop\n .endr":::); } (void)n; }
int main(){
  memset(buf, 0, sizeof buf); buf[0]=(uint64_t)&buf[0];
  B(b_iadd,0,"dependent int ADD (latency)");
  B(b_iadd_t,0,"independent int ADD x4 (throughput)");
  B(b_imul,0,"dependent int MUL");
  B(b_idiv,0,"dependent udiv (fixed ÷7)");
  B(b_fadd,0,"dependent FP32 FADD");
  B(b_fmul,0,"dependent FP32 FMUL");
  B(b_fsqrt,0,"dependent FP32 FSQRT");
  B(b_fdiv,0,"dependent FP32 FDIV (half-rept)");
  B(b_crc,0,"dependent CRC32X");
  B(b_aes,0,"dependent AESD");
  B(b_sha,0,"dependent SHA256H");
  B(b_cas,0,"dependent CASAL (LSE)");
  B(b_ld,0,"dependent LDR (L1 hit, self-ref)");
  B(b_st,0,"STR same line (store buf)");
  B(b_zva,0,"DC ZVA 64B");
  B(b_br,0,"B.cond not-taken (throughput)");
  B(b_nop,0,"NOP x100 (retire width)");
  return 0;
}
EOF
