#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static inline uint64_t cntv(void){ uint64_t v; asm volatile("mrs %0, cntvct_el0":"=r"(v)); return v; }
static uint64_t *buf;
// streaming loads over 32KB (L1)
static void loads_L1(uint64_t n){
  uint64_t s=0;
  for(uint64_t r=0;r<2000;r++)
    for(uint64_t i=0;i<n;i+=8){
      asm volatile("ldp x9,x10,[%0],#16"::"r"(buf+i):"x9","x10");
      asm volatile("ldp x11,x12,[%0],#16"::"r"(buf+i+2):"x11","x12");
    }
  (void)s;
}
int main(int argc, char**argv){
  size_t bytes = argc>1? atol(argv[1]) : 32*1024;
  size_t n = bytes/8;
  buf = aligned_alloc(64, bytes);
  memset(buf,1,bytes);
  uint64_t t0=cntv();
  loads_L1(n);
  uint64_t t1=cntv();
  double total_bytes = 2000.0*bytes*2; // 2 ldp per i-step... careful: i+=8 and two ldp at i and i+2 → double counting
  // simpler: count insts: per i iter (8 words=64B) we issue 2 ldp = 32B each → 64B per iter. iters = n/8
  double bytes_moved = 2000.0*(n/8)*64.0;
  printf("workload=%zuB  bytes=%.1fMB  time=%.3fms  BW=%.1f GB/s\n",
    bytes, bytes_moved/1e6, (t1-t0)/100.0, bytes_moved/((t1-t0)/100.0/1e3)/1e9);
  return 0;
}
